import{_ as t,o as a,c as n,a2 as s}from"./chunks/framework.hw3Av5Vn.js";const g=JSON.parse('{"title":"Video Game","description":"","frontmatter":{},"headers":[],"relativePath":"demos/VIDEO_GAME.md","filePath":"demos/VIDEO_GAME.md"}'),i={name:"demos/VIDEO_GAME.md"};function o(r,e,l,m,d,h){return a(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="video-game" tabindex="-1">Video Game <a class="header-anchor" href="#video-game" aria-label="Permalink to &quot;Video Game&quot;">​</a></h1><p>The demo songs in the video game style. Each is described below, with the features it uses; <a href="./../DEMOS">About Demos</a> lists every demo.</p><ul><li><a href="#fang_removal">Gothic Stage Theme</a>: <code>fang_removal.yml</code></li><li><a href="#incoming_message">Ten Stages</a>: <code>incoming_message.yml</code></li></ul><p><a id="fang_removal"></a></p><h2 id="gothic-stage-theme-fang-removal-yml" tabindex="-1">Gothic Stage Theme: <code>fang_removal.yml</code> <a class="header-anchor" href="#gothic-stage-theme-fang-removal-yml" aria-label="Permalink to &quot;Gothic Stage Theme: `fang_removal.yml`&quot;">​</a></h2><p>A gothic eight-bit stage theme in the manner of Castlevania&#39;s Vampire Killer, in D harmonic minor, whose major fifth chord gives the style its pull: a square-wave lead, a second square two scale steps below and a driving octave bass. The melody is its own.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/video_game/fang_removal.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/video_game/fang_removal.yml</code></a> · D harmonic minor · 150 BPM · 2:59 · 9 scenes · 6 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="incoming_message"></a></p><h2 id="ten-stages-incoming-message-yml" tabindex="-1">Ten Stages: <code>incoming_message.yml</code> <a class="header-anchor" href="#ten-stages-incoming-message-yml" aria-label="Permalink to &quot;Ten Stages: `incoming_message.yml`&quot;">​</a></h2><p>Nine minutes after Mega Man 2&#39;s intro and boss themes: ten stages, each in a key of its own set by its scenes, changing theme exactly nine times with a one-bar fill between each, the last a reprise of the first. Each stage&#39;s patterns are named after it, stage_0 to stage_9, and a chip track breaks its chords into thirty-second notes as the old sound chips did.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/video_game/incoming_message.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/video_game/incoming_message.yml</code></a> · E minor · 150 BPM · 8:46 · 29 scenes · 12 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">arps</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">key changes</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table>',13)])])}const _=t(i,[["render",o]]);export{g as __pageData,_ as default};
